	b.WriteString(fmt.Sprintf("%s %s\n",
		highlightStyle.Render("Method:"),
		methodStyle(wh.Method),
	))
	b.WriteString(fmt.Sprintf("%s %s\n", highlightStyle.Render("Path:"), wh.Path))
